import React, { useState } from "react";

export default function App() {
  const [screen, setScreen] = useState("home");
  const [feeling, setFeeling] = useState("");
  const [mealInput, setMealInput] = useState("");
  const [meals, setMeals] = useState([]);

  const feelingButtonStyle = (value) => ({
    padding: "12px 18px",
    borderRadius: "12px",
    border: feeling === value ? "2px solid #10b981" : "1px solid #d1d5db",
    backgroundColor: feeling === value ? "#ecfdf5" : "white",
    color: "#111827",
    fontSize: "16px",
    cursor: "pointer",
    minWidth: "90px",
    fontWeight: "500",
  });

  const mainButton = {
    padding: "14px 18px",
    borderRadius: "14px",
    border: "none",
    backgroundColor: "#10b981",
    color: "white",
    fontSize: "16px",
    fontWeight: "600",
    cursor: "pointer",
    width: "100%",
    marginTop: "16px",
  };

  const secondaryButton = {
    padding: "12px 18px",
    borderRadius: "14px",
    border: "1px solid #d1d5db",
    backgroundColor: "white",
    color: "#111827",
    fontSize: "16px",
    cursor: "pointer",
    width: "100%",
    marginTop: "12px",
  };

  const saveMeal = () => {
    if (mealInput.trim() === "") return;
    setMeals([...meals, mealInput]);
    setMealInput("");
    setScreen("home");
  };

  return (
    <div
      dir="rtl"
      style={{
        minHeight: "100vh",
        backgroundColor: "#f8fafc",
        fontFamily: "Arial, sans-serif",
        padding: "24px 16px",
      }}
    >
      <div
        style={{
          maxWidth: "420px",
          margin: "0 auto",
        }}
      >
        {screen === "home" && (
          <>
            <div
              style={{
                background: "linear-gradient(135deg, #10b981, #34d399)",
                color: "white",
                borderRadius: "24px",
                padding: "24px",
                boxShadow: "0 10px 30px rgba(16,185,129,0.18)",
                marginBottom: "18px",
              }}
            >
              <div style={{ fontSize: "14px", opacity: 0.95, marginBottom: "8px" }}>
                ברוך הבא
              </div>
              <h1 style={{ margin: 0, fontSize: "34px", lineHeight: "1.2" }}>
                מה בטוח לי לאכול היום?
              </h1>
            </div>

            <div
              style={{
                backgroundColor: "white",
                borderRadius: "20px",
                padding: "20px",
                boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
                marginBottom: "16px",
              }}
            >
              <h3 style={{ marginTop: 0, marginBottom: "14px", fontSize: "22px", color: "#111827" }}>
                איך אתה מרגיש היום?
              </h3>

              <div
                style={{
                  display: "flex",
                  gap: "10px",
                  flexWrap: "wrap",
                  marginBottom: "14px",
                }}
              >
                <button style={feelingButtonStyle("טוב")} onClick={() => setFeeling("טוב")}>
                  טוב
                </button>
                <button style={feelingButtonStyle("סביר")} onClick={() => setFeeling("סביר")}>
                  סביר
                </button>
                <button style={feelingButtonStyle("לא טוב")} onClick={() => setFeeling("לא טוב")}>
                  לא טוב
                </button>
              </div>

              <div
                style={{
                  fontSize: "15px",
                  color: "#4b5563",
                  backgroundColor: "#f9fafb",
                  borderRadius: "12px",
                  padding: "12px",
                }}
              >
                מצב נוכחי: <strong>{feeling || "עוד לא נבחר"}</strong>
              </div>
            </div>

            <div
              style={{
                backgroundColor: "white",
                borderRadius: "20px",
                padding: "20px",
                boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
                marginBottom: "16px",
              }}
            >
              <h3 style={{ marginTop: 0, marginBottom: "14px", fontSize: "22px", color: "#111827" }}>
                מה כדאי לך לאכול היום
              </h3>

              <div style={{ display: "grid", gap: "10px" }}>
                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  אורז עם עוף
                </div>

                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  מרק ירקות
                </div>

                <div
                  style={{
                    backgroundColor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                    borderRadius: "14px",
                    padding: "14px",
                    fontSize: "16px",
                  }}
                >
                  חביתה
                </div>
              </div>

              <button style={mainButton} onClick={() => setScreen("add")}>
                הוספת ארוחה
              </button>
            </div>

            <div
              style={{
                backgroundColor: "white",
                borderRadius: "20px",
                padding: "20px",
                boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
              }}
            >
              <h3 style={{ marginTop: 0, marginBottom: "14px", fontSize: "22px", color: "#111827" }}>
                מה אכלתי היום
              </h3>

              {meals.length === 0 ? (
                <p style={{ color: "#6b7280", margin: 0 }}>עדיין לא הוספת ארוחות</p>
              ) : (
                <ul style={{ paddingRight: "20px", margin: 0 }}>
                  {meals.map((meal, index) => (
                    <li key={index} style={{ marginBottom: "10px", fontSize: "16px", color: "#111827" }}>
                      {meal}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </>
        )}

        {screen === "add" && (
          <div
            style={{
              backgroundColor: "white",
              borderRadius: "20px",
              padding: "20px",
              boxShadow: "0 6px 20px rgba(15,23,42,0.06)",
            }}
          >
            <h1 style={{ marginTop: 0, fontSize: "30px", color: "#111827" }}>הוספת ארוחה</h1>

            <p style={{ color: "#6b7280", marginBottom: "14px" }}>
              כתוב מה אכלת ושמור
            </p>

            <input
              placeholder="מה אכלת?"
              value={mealInput}
              onChange={(e) => setMealInput(e.target.value)}
              style={{
                width: "100%",
                padding: "14px",
                borderRadius: "14px",
                border: "1px solid #d1d5db",
                fontSize: "16px",
                boxSizing: "border-box",
                marginBottom: "12px",
              }}
            />

            <button style={mainButton} onClick={saveMeal}>
              שמור ארוחה
            </button>

            <button style={secondaryButton} onClick={() => setScreen("home")}>
              חזור למסך הבית
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
